module qam16_mapper_interpolated #(
    parameter int unsigned N = 4,
    parameter int unsigned IN_WIDTH = 4,
    parameter int unsigned OUT_WIDTH = 3
)(
    input  logic [N * IN_WIDTH - 1 : 0] bits,
    output logic [(N + N/2) * OUT_WIDTH - 1 : 0] I,
    output logic [(N + N/2) * OUT_WIDTH - 1 : 0] Q
);

    localparam int unsigned NUM_INTERP = N / 2;

    logic [N-1:0][OUT_WIDTH-1:0] i_map;
    logic [N-1:0][OUT_WIDTH-1:0] q_map;
    logic [NUM_INTERP-1:0][OUT_WIDTH-1:0] i_int;
    logic [NUM_INTERP-1:0][OUT_WIDTH-1:0] q_int;

    always_comb begin
        for (int k = 0; k < N; k++) begin
            logic [IN_WIDTH-1:0] sym;
            for (int b = 0; b < IN_WIDTH; b++) sym[b] = bits[k * IN_WIDTH + b];

            case (sym[3:2])
                2'b00: i_map[k] = 3'sd-3;
                2'b01: i_map[k] = 3'sd-1;
                2'b10: i_map[k] = 3'sd1;
                2'b11: i_map[k] = 3'sd3;
            endcase

            case (sym[1:0])
                2'b00: q_map[k] = 3'sd-3;
                2'b01: q_map[k] = 3'sd-1;
                2'b10: q_map[k] = 3'sd1;
                2'b11: q_map[k] = 3'sd3;
            endcase
        end
    end

    always_comb begin
        for (int k = 0; k < NUM_INTERP; k++) begin
            logic signed [OUT_WIDTH:0] sum_i;
            logic signed [OUT_WIDTH:0] sum_q;
            sum_i = $signed(i_map[2*k]) + $signed(i_map[2*k+1]);
            sum_q = $signed(q_map[2*k]) + $signed(q_map[2*k+1]);

            i_int[k] = $unsigned(sum_i >>> 1);
            q_int[k] = $unsigned(sum_q >>> 1);
        end
    end

    always_comb begin
        int i_idx = 0;
        int q_idx = 0;
        for (int k = 0; k < NUM_INTERP; k++) begin
            for (int b = 0; b < OUT_WIDTH; b++) I[i_idx + b] = i_map[2*k][b];
            i_idx += OUT_WIDTH;
            for (int b = 0; b < OUT_WIDTH; b++) I[i_idx + b] = i_int[k][b];
            i_idx += OUT_WIDTH;
            for (int b = 0; b < OUT_WIDTH; b++) I[i_idx + b] = i_map[2*k+1][b];
            i_idx += OUT_WIDTH;

            for (int b = 0; b < OUT_WIDTH; b++) Q[q_idx + b] = q_map[2*k][b];
            q_idx += OUT_WIDTH;
            for (int b = 0; b < OUT_WIDTH; b++) Q[q_idx + b] = q_int[k][b];
            q_idx += OUT_WIDTH;
            for (int b = 0; b < OUT_WIDTH; b++) Q[q_idx + b] = q_map[2*k+1][b];
            q_idx += OUT_WIDTH;
        end
    end
endmodule

